function asyncRunner(generatorFn) {
  return new Promise((resolve, reject) => {
    const iterator = generatorFn();
    function stepFn (action, args) {
      try {
        const result = iterator[action](args);
        const { value, done } = result;
        if (done) {
          resolve(value);
          return;
        }
        Promise.resolve(value).then(val => {
          stepFn('next', val);
        }).catch(e => {
          stepFn('throw', e);
        })
      } catch(e) {
        reject(e);
      }
    }
    stepFn('next')
  })
}

const sleep = (ms) => {
  return new Promise(resolve => {
    setTimeout(() => {
      resolve(`sleep ${ms}ms ${new Date().getSeconds()}`)
    }, ms)
  })
}

function *task() {
  console.log('task start', new Date().getSeconds())

  const result1 = yield sleep(1000);
  console.log(result1);
  const result2 = yield sleep(2000);
  console.log(result2);

  return `task end ${new Date().getSeconds()}`;
}

asyncRunner(task).then(val => {
  console.log(val)
})
